-- Existing text data is retained; only exact normalized matches get a central model FK.
UPDATE product_vehicle_compatibilities c SET vehicle_model_id=m.id FROM vehicle_brands b JOIN vehicle_models m ON m.brand_id=b.id WHERE lower(regexp_replace(trim(c.vehicle_brand), '[[:space:]]+', ' ', 'g'))=b.normalized_name AND lower(regexp_replace(trim(c.vehicle_model), '[[:space:]]+', ' ', 'g'))=m.normalized_name AND c.vehicle_model_id IS NULL;
